/* HT.events — era 06: the long nineteenth century to 1945 (ce(1800) – ce(1945, 9, 2))
 *
 * Tier = coarsest view at which the event appears, judged against all of human history
 * (CONTRACT.md §3). Events after 1900 carry day precision wherever the date is well known.
 * Events are listed in chronological order. Every event carries a `link` to the English
 * Wikipedia article about it.
 */
(function (root) {
  'use strict';
  const HT = root.HT || (root.HT = {});
  const { bce, ce, ymd, ya } = HT.time;
  HT.events = HT.events || [];
  HT.events.push(
    // ---- 1800s – 1810s ---------------------------------------------------------------
    { t: ymd(1800, 3, 20), title: 'Volta announces the electric battery',
      detail: 'In a letter to the Royal Society, Alessandro Volta described a pile of zinc and copper discs separated by brine-soaked cloth that gave a steady electric current, the first battery and the starting point of electrochemistry and electrical science.',
      tier: 4, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Voltaic_pile' },
    { t: ymd(1803, 5, 18), end: ymd(1815, 11, 20), title: 'Napoleonic Wars',
      detail: 'Napoleon\'s France fought shifting coalitions across Europe, from Austerlitz to Moscow to Waterloo; the wars spread the Napoleonic Code, dissolved the Holy Roman Empire and remade the European order.',
      tier: 3, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Napoleonic_Wars' },
    { t: ymd(1804, 1, 1), title: 'Haiti declares independence',
      detail: 'Jean-Jacques Dessalines proclaimed the former French colony of Saint-Domingue free after the only successful slave revolution in history, making Haiti the first Black republic and the second independent nation in the Americas.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Haitian_Declaration_of_Independence' },
    { t: ymd(1807, 3, 25), title: 'Britain outlaws the slave trade',
      detail: 'After a twenty-year campaign led by Thomas Clarkson and William Wilberforce, the Slave Trade Act made it illegal for British subjects to carry enslaved people; the Royal Navy\'s West Africa Squadron then began intercepting slave ships.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Slave_Trade_Act_1807' },
    { t: ymd(1810), end: ymd(1825), title: 'Latin American wars of independence',
      detail: 'From Mexico to Argentina, revolutions led by Bolívar, San Martín, Hidalgo and others threw off Spanish and Portuguese rule, creating more than a dozen new republics by the mid-1820s.',
      tier: 3, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Spanish_American_wars_of_independence' },
    { t: ymd(1815, 4, 10), title: 'Mount Tambora erupts, the largest eruption in recorded history',
      detail: 'The Indonesian volcano blew some 150 cubic kilometres of rock into the sky, killing tens of thousands nearby; its sulphur veil cooled the globe and caused the "Year Without a Summer" of 1816, with crop failures and famine across Europe and North America.',
      tier: 5, category: 'civilization',
      link: 'https://en.wikipedia.org/wiki/1815_eruption_of_Mount_Tambora' },
    { t: ymd(1815, 6, 18), title: 'Napoleon defeated at Waterloo',
      detail: 'Wellington\'s Anglo-allied army and Blücher\'s Prussians crushed Napoleon\'s last army near Brussels, ending his Hundred Days; he was exiled to Saint Helena and Europe entered decades of relative peace.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Battle_of_Waterloo' },
    { t: ymd(1816), title: 'Shaka becomes king of the Zulu and builds a military empire',
      detail: 'Shaka reorganized the Zulu into disciplined age regiments armed with the short stabbing spear and conquered his neighbours across what is now KwaZulu-Natal, setting off the upheavals of the Mfecane across southern Africa.',
      tier: 6, category: 'empire',
      link: 'https://en.wikipedia.org/wiki/Shaka' },
    { t: ymd(1818, 1, 1), title: 'Mary Shelley publishes Frankenstein',
      detail: 'Begun when she was 18 during a rainy summer with Byron and Shelley at Lake Geneva, Mary Shelley\'s tale of a scientist who animates a creature and abandons it was published anonymously and became the founding work of science fiction.',
      tier: 6, category: 'art',
      link: 'https://en.wikipedia.org/wiki/Frankenstein' },

    // ---- 1820s – 1840s ---------------------------------------------------------------
    { t: ymd(1822, 9, 7), title: 'Brazil declares independence from Portugal',
      detail: 'On the banks of the Ipiranga, Prince Pedro cried "Independence or death!" and was crowned Emperor Pedro I, making Brazil an independent monarchy that kept slavery until 1888 and became a republic in 1889.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Independence_of_Brazil' },
    { t: ymd(1824, 5, 7), title: 'Beethoven\'s Ninth Symphony premieres in Vienna',
      detail: 'The deaf composer\'s last symphony, ending with the choral "Ode to Joy", was received with an ovation he could not hear; it became the defining work of Romantic music.',
      tier: 6, category: 'art',
      link: 'https://en.wikipedia.org/wiki/Symphony_No._9_(Beethoven)' },
    { t: ymd(1830, 4, 6), title: 'Joseph Smith founds the Church of Jesus Christ of Latter-day Saints',
      detail: 'Weeks after publishing the Book of Mormon, Smith organized the church in Fayette, New York; persecution drove its members west to Utah, and it grew into a worldwide faith.',
      tier: 7, category: 'religion',
      link: 'https://en.wikipedia.org/wiki/Church_of_Jesus_Christ_of_Latter-day_Saints' },
    { t: ymd(1830, 7, 5), title: 'France captures Algiers and begins the conquest of Algeria',
      detail: 'Three weeks after landing at Sidi Ferruch, a French army took the city and deposed the Ottoman dey; the conquest of the interior took decades and cost hundreds of thousands of Algerian lives, and Algeria remained French until 1962.',
      tier: 5, category: 'empire',
      link: 'https://en.wikipedia.org/wiki/Invasion_of_Algiers_in_1830' },
    { t: ymd(1830, 9, 15), title: 'Liverpool and Manchester Railway opens, the first inter-city passenger line',
      detail: 'Hauled by Stephenson locomotives like the Rocket, the first railway to rely entirely on steam power and a timetable set off a worldwide railway boom that shrank distances and built modern economies.',
      tier: 3, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Liverpool_and_Manchester_Railway' },
    { t: ymd(1831, 8, 29), title: 'Faraday discovers electromagnetic induction',
      detail: 'Michael Faraday found that a changing magnetic field induces an electric current, the principle behind every generator, transformer and electric motor and the basis of the electrical age.',
      tier: 4, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Electromagnetic_induction' },
    { t: ymd(1833, 8, 28), title: 'Britain\'s Slavery Abolition Act outlaws slavery across most of the empire',
      detail: 'After decades of campaigning by Wilberforce and the abolitionists, Parliament freed some 800,000 enslaved people in the Caribbean, Mauritius and the Cape, a milestone in the global end of chattel slavery.',
      tier: 4, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Slavery_Abolition_Act_1833' },
    { t: ymd(1837, 6, 20), end: ymd(1901, 1, 22), title: 'Reign of Queen Victoria',
      detail: 'The 18-year-old Victoria inherited the throne and reigned for 63 years over a Britain that industrialized, extended its empire across a quarter of the world and gave its name to an age of railways, factories and reform.',
      tier: 4, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Queen_Victoria' },
    { t: ymd(1839, 8, 19), title: 'Daguerreotype process announced in Paris',
      detail: 'The French Academy of Sciences published Louis Daguerre\'s method for fixing an image on a silvered copper plate, free to the world, and practical photography spread within months.',
      tier: 4, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Daguerreotype' },
    { t: ymd(1839, 9, 4), end: ymd(1842, 8, 29), title: 'First Opium War',
      detail: 'Britain went to war to force China to keep accepting opium imports; the Treaty of Nanking ceded Hong Kong, opened treaty ports and began what China calls its century of humiliation.',
      tier: 5, category: 'empire',
      link: 'https://en.wikipedia.org/wiki/First_Opium_War' },
    { t: ymd(1840, 2, 6), title: 'Treaty of Waitangi signed between Māori chiefs and the British Crown',
      detail: 'Some 40 chiefs signed at Waitangi and hundreds more around the country; disputes over what the English and Māori texts ceded have shaped New Zealand politics ever since, and the day is its national holiday.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Treaty_of_Waitangi' },
    { t: ymd(1843, 9), title: 'Ada Lovelace publishes the first computer program',
      detail: 'In her notes to a paper on Babbage\'s Analytical Engine, Lovelace set out a step-by-step method for the machine to compute Bernoulli numbers and foresaw that such an engine could manipulate symbols and compose music, not just crunch numbers.',
      tier: 5, category: 'computing',
      link: 'https://en.wikipedia.org/wiki/Ada_Lovelace' },
    { t: ymd(1844, 5, 24), title: 'Morse telegraphs "What hath God wrought" from Washington to Baltimore',
      detail: 'Samuel Morse\'s demonstration line proved electric telegraphy practical; within decades wires spanned continents and oceans, separating communication from transport for the first time.',
      tier: 3, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Samuel_Morse' },
    { t: ymd(1845), end: ymd(1852), title: 'Great Irish Famine',
      detail: 'Potato blight destroyed the crop that most of rural Ireland depended on; about a million people died and another million emigrated, cutting the population by a quarter.',
      tier: 5, category: 'agriculture',
      link: 'https://en.wikipedia.org/wiki/Great_Famine_(Ireland)' },
    { t: ymd(1846, 10, 16), title: 'First public demonstration of ether anaesthesia',
      detail: 'At Massachusetts General Hospital, William Morton put a patient to sleep with ether while a surgeon removed a neck tumour painlessly, the beginning of modern surgery.',
      tier: 5, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/William_T._G._Morton' },
    { t: ymd(1847, 5), title: 'Semmelweis makes doctors wash their hands, cutting childbed fever deaths',
      detail: 'At the Vienna General Hospital, Ignaz Semmelweis ordered staff to scrub with chlorinated lime between the dissecting room and the maternity ward; deaths from puerperal fever fell from over 10 per cent to about 1 per cent, though his colleagues rejected the idea.',
      tier: 5, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/Ignaz_Semmelweis' },
    { t: ymd(1848, 1, 12), end: ymd(1849, 8, 13), title: 'Revolutions of 1848 sweep across Europe',
      detail: 'Beginning in Sicily and Paris, uprisings for constitutions, national unity and workers\' rights toppled Louis Philippe and shook Vienna, Berlin, Budapest and Rome; most were crushed within a year, but serfdom ended in Austria and the ideas endured.',
      tier: 4, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Revolutions_of_1848' },
    { t: ymd(1848, 2, 21), title: 'Marx and Engels publish The Communist Manifesto',
      detail: 'Published in London on the eve of the 1848 revolutions, the pamphlet framed history as class struggle and called on workers of the world to unite, becoming the founding text of communism.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/The_Communist_Manifesto' },
    { t: ymd(1848, 7, 19), end: ymd(1848, 7, 20), title: 'Seneca Falls Convention launches the women\'s rights movement',
      detail: 'Organized by Elizabeth Cady Stanton and Lucretia Mott in upstate New York, the first women\'s rights convention adopted a Declaration of Sentiments modelled on the Declaration of Independence and demanded the vote for women.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Seneca_Falls_Convention' },

    // ---- 1850s – 1860s ---------------------------------------------------------------
    { t: ymd(1850, 12), end: ymd(1864, 8), title: 'Taiping Rebellion',
      detail: 'Hong Xiuquan, who believed himself the younger brother of Jesus, led a millenarian revolt that seized Nanjing and fought the Qing for 14 years; with 20–30 million dead it was among the bloodiest wars ever fought.',
      tier: 4, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Taiping_Rebellion' },
    { t: ymd(1853, 7, 8), title: 'Commodore Perry\'s black ships arrive in Japan',
      detail: 'Four US Navy warships steamed into Uraga Bay with a demand that Japan open its ports; the Convention of Kanagawa followed in 1854, ending two centuries of seclusion and setting off the crisis that toppled the shogunate.',
      tier: 5, category: 'empire',
      link: 'https://en.wikipedia.org/wiki/Perry_Expedition' },
    { t: ymd(1853, 10, 16), end: ymd(1856, 3, 30), title: 'Crimean War',
      detail: 'Britain, France and the Ottomans fought Russia in the Crimea in a war remembered for the Charge of the Light Brigade, the first war correspondents and photographers, and Florence Nightingale\'s nursing at Scutari, which founded modern nursing.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Crimean_War' },
    { t: ymd(1857, 5, 10), end: ymd(1858, 11, 1), title: 'Indian Rebellion of 1857',
      detail: 'Sepoys of the East India Company army mutinied at Meerut and marched on Delhi, where they restored the last Mughal emperor; after a year of savage fighting Britain abolished the Company and placed India under direct Crown rule.',
      tier: 4, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Indian_Rebellion_of_1857' },
    { t: ymd(1859, 11, 24), title: 'Darwin publishes On the Origin of Species',
      detail: 'Charles Darwin laid out evolution by natural selection with evidence gathered over two decades, giving biology its unifying theory and transforming how humans understand their own origins.',
      tier: 1, category: 'science',
      link: 'https://en.wikipedia.org/wiki/On_the_Origin_of_Species' },
    { t: ymd(1861), title: 'Pasteur\'s swan-neck flask experiments disprove spontaneous generation',
      detail: 'Louis Pasteur showed that microbes come from the air rather than arising spontaneously, founding modern microbiology and paving the way for the germ theory of disease that led to pasteurization, antiseptic surgery and vaccines.',
      tier: 3, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/Louis_Pasteur' },
    { t: ymd(1861, 4, 12), end: ymd(1865, 4, 9), title: 'American Civil War',
      detail: 'The Confederate attack on Fort Sumter opened four years of war that killed some 750,000 Americans, preserved the Union and, through the Emancipation Proclamation and 13th Amendment, ended slavery in the United States.',
      tier: 3, category: 'war',
      link: 'https://en.wikipedia.org/wiki/American_Civil_War' },
    { t: ymd(1865, 2, 8), title: 'Mendel presents his laws of inheritance',
      detail: 'Gregor Mendel told the Brünn Natural History Society how eight years of pea-plant crosses revealed that traits pass on as discrete factors in fixed ratios; ignored for 35 years, his paper became the foundation of genetics when rediscovered in 1900.',
      tier: 5, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Gregor_Mendel' },
    { t: ymd(1865, 8, 12), title: 'Lister performs the first antiseptic surgery',
      detail: 'Applying Pasteur\'s germ theory, Joseph Lister dressed a boy\'s compound leg fracture in Glasgow with carbolic acid and it healed without infection; antiseptic and then aseptic technique cut surgical death rates dramatically.',
      tier: 5, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/Joseph_Lister' },
    { t: ymd(1868, 1, 3), title: 'Meiji Restoration returns power to the emperor of Japan',
      detail: 'Samurai from Satsuma and Chōshū overthrew the Tokugawa shogunate in the name of the young Emperor Meiji, launching a crash programme of Westernization that made Japan an industrial and military power within a generation.',
      tier: 3, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Meiji_Restoration' },
    { t: ymd(1869, 3, 6), title: 'Mendeleev presents the periodic table',
      detail: 'Dmitri Mendeleev arranged the 63 known elements by atomic weight and chemical properties, leaving gaps whose later-discovered elements such as gallium and germanium confirmed his system.',
      tier: 5, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Dmitri_Mendeleev' },
    { t: ymd(1869, 11, 17), title: 'Suez Canal opens',
      detail: 'Ferdinand de Lesseps\'s canal linked the Mediterranean to the Red Sea, cutting the sea route from Europe to India by thousands of miles and making Egypt a strategic prize for the imperial powers.',
      tier: 4, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Suez_Canal' },

    // ---- 1870s – 1890s ---------------------------------------------------------------
    { t: ymd(1871, 1, 18), title: 'German Empire proclaimed in the Hall of Mirrors at Versailles',
      detail: 'After Bismarck\'s victory over France, Wilhelm I of Prussia was proclaimed German Emperor, uniting the German states into a single power that upset the balance of Europe.',
      tier: 4, category: 'empire',
      link: 'https://en.wikipedia.org/wiki/Proclamation_of_the_German_Empire' },
    { t: ymd(1874, 4, 15), title: 'Impressionists hold their first exhibition in Paris',
      detail: 'Monet, Renoir, Degas, Pissarro, Cézanne and Morisot showed their work independently of the official Salon at the studio of the photographer Nadar; a mocking review of Monet\'s Impression, Sunrise gave the movement its name.',
      tier: 7, category: 'art',
      link: 'https://en.wikipedia.org/wiki/Impressionism' },
    { t: ymd(1876, 3, 10), title: 'Bell makes the first telephone call',
      detail: 'Three days after his patent was granted, Alexander Graham Bell spoke "Mr Watson, come here, I want to see you" into his transmitter in Boston, and speech travelled by wire for the first time.',
      tier: 3, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Alexander_Graham_Bell' },
    { t: ymd(1879, 10, 22), title: 'Edison perfects a practical incandescent light bulb',
      detail: 'At Menlo Park, Thomas Edison\'s team ran a carbon-filament lamp for more than 13 hours, the first practical long-lasting electric light, and went on to build the generating stations and grids that electrified cities.',
      tier: 2, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Incandescent_light_bulb' },
    { t: ymd(1882, 3, 24), title: 'Koch identifies the bacterium that causes tuberculosis',
      detail: 'Robert Koch announced in Berlin that a single microbe caused the disease then killing one in seven Europeans, proving germ theory for a major human illness and setting the standard for identifying pathogens.',
      tier: 6, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/Robert_Koch' },
    { t: ymd(1883, 8, 27), title: 'Krakatoa erupts, heard 4,800 km away',
      detail: 'The Indonesian volcano destroyed itself in the loudest sound in recorded history; tsunamis up to 30 metres high killed some 36,000 people on Java and Sumatra, and its dust reddened sunsets around the world for years.',
      tier: 5, category: 'civilization',
      link: 'https://en.wikipedia.org/wiki/1883_eruption_of_Krakatoa' },
    { t: ymd(1884, 11, 15), end: ymd(1885, 2, 26), title: 'Berlin Conference sets the rules for the partition of Africa',
      detail: 'Convened by Bismarck, the European powers agreed how to claim African territory without consulting a single African; by 1914 nearly the whole continent was under colonial rule.',
      tier: 4, category: 'empire',
      link: 'https://en.wikipedia.org/wiki/Berlin_Conference' },
    { t: ymd(1886, 1, 29), title: 'Karl Benz patents the first automobile',
      detail: 'Benz\'s three-wheeled Patent-Motorwagen, driven by a single-cylinder petrol engine, is generally counted as the first practical car; his wife Bertha\'s 106-km drive in 1888 proved it roadworthy.',
      tier: 4, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Benz_Patent-Motorwagen' },
    { t: ymd(1888, 5, 13), title: 'Brazil abolishes slavery, the last country in the Americas to do so',
      detail: 'Princess Isabel signed the Lei Áurea (Golden Law) freeing some 700,000 enslaved people without compensation to owners; the planters\' anger helped bring down the monarchy the following year.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Lei_%C3%81urea' },
    { t: ymd(1892, 1, 1), title: 'Ellis Island immigration station opens in New York Harbor',
      detail: 'Fifteen-year-old Annie Moore from Ireland was the first of some 12 million immigrants processed at Ellis Island, the gateway of the great European migration to the United States.',
      tier: 7, category: 'migration',
      link: 'https://en.wikipedia.org/wiki/Ellis_Island' },
    { t: ymd(1893, 9, 19), title: 'New Zealand becomes the first country to give women the vote',
      detail: 'After a petition of some 32,000 signatures gathered by Kate Sheppard\'s suffragists, Governor Lord Glasgow signed the Electoral Act granting all women the right to vote in national elections.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Women%27s_suffrage_in_New_Zealand' },
    { t: ymd(1894, 7, 25), end: ymd(1895, 4, 17), title: 'First Sino-Japanese War',
      detail: 'Japan\'s modernized army and navy routed Qing China on land in Korea and at sea off the Yalu; the Treaty of Shimonoseki ceded Taiwan to Japan, ended Chinese suzerainty over Korea and announced Japan as East Asia\'s rising power.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/First_Sino-Japanese_War' },
    { t: ymd(1895, 11, 8), title: 'Röntgen discovers X-rays',
      detail: 'Experimenting with cathode-ray tubes in Würzburg, Wilhelm Röntgen found invisible rays that passed through flesh and exposed photographic plates; within months doctors were imaging bones, and he won the first Nobel Prize in Physics.',
      tier: 5, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Wilhelm_R%C3%B6ntgen' },
    { t: ymd(1895, 12, 28), title: 'Lumière brothers hold the first public film screening',
      detail: 'Auguste and Louis Lumière projected ten short films to a paying audience at the Grand Café in Paris, launching cinema as a mass medium.',
      tier: 5, category: 'art',
      link: 'https://en.wikipedia.org/wiki/Auguste_and_Louis_Lumi%C3%A8re' },
    { t: ymd(1896, 3, 1), title: 'Ethiopia defeats Italy at the Battle of Adwa',
      detail: 'Emperor Menelik II\'s army of some 100,000 destroyed an invading Italian force in the mountains of Tigray; Italy recognized Ethiopian independence, and Adwa became a symbol of African resistance to the colonial scramble.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Battle_of_Adwa' },
    { t: ymd(1896, 4, 6), end: ymd(1896, 4, 15), title: 'First modern Olympic Games held in Athens',
      detail: 'Pierre de Coubertin\'s revival of the ancient games drew 241 athletes from 14 nations to the restored Panathenaic Stadium.',
      tier: 7, category: 'civilization',
      link: 'https://en.wikipedia.org/wiki/1896_Summer_Olympics' },
    { t: ymd(1897, 8, 29), title: 'Theodor Herzl convenes the First Zionist Congress in Basel',
      detail: 'Some 200 delegates adopted the goal of a legally secured home for the Jewish people in Palestine, turning Zionism into an organized political movement.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/First_Zionist_Congress' },
    { t: ymd(1898, 12, 26), title: 'Marie and Pierre Curie announce the discovery of radium',
      detail: 'Having found polonium in July, the Curies reported a second, intensely radioactive element extracted from tonnes of pitchblende; Marie Curie coined the word radioactivity and became the first person to win two Nobel Prizes.',
      tier: 5, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Marie_Curie' },

    // ---- 1900s – 1910s ---------------------------------------------------------------
    { t: ymd(1900, 12, 14), title: 'Planck introduces the quantum to explain black-body radiation',
      detail: 'Max Planck told the German Physical Society that his radiation law only worked if energy were emitted in discrete packets proportional to frequency, E = hν, the reluctant first step of quantum theory.',
      tier: 5, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Max_Planck' },
    { t: ymd(1901, 12, 12), title: 'Marconi receives the first transatlantic radio signal',
      detail: 'At Signal Hill in Newfoundland, Guglielmo Marconi heard the Morse letter S sent from Poldhu in Cornwall, 3,500 km away, proving that wireless could span oceans.',
      tier: 5, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Guglielmo_Marconi' },
    { t: ymd(1903, 12, 17), title: 'Wright brothers make the first powered flight at Kitty Hawk',
      detail: 'Orville Wright flew the Flyer 120 feet in 12 seconds over the dunes of North Carolina, the first controlled, sustained flight of a heavier-than-air powered aircraft.',
      tier: 1, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Wright_Flyer' },
    { t: ymd(1904, 1, 12), end: ymd(1908), title: 'Herero and Nama genocide in German South West Africa',
      detail: 'After the Herero rose against colonial rule, General von Trotha ordered their extermination; survivors were driven into the Omaheke desert or worked to death in camps, killing some 65,000 Herero and 10,000 Nama, the first genocide of the 20th century.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Herero_and_Nama_genocide' },
    { t: ymd(1904, 2, 8), end: ymd(1905, 9, 5), title: 'Russo-Japanese War',
      detail: 'Japan\'s surprise attack on the Russian fleet at Port Arthur opened a war it won on land at Mukden and at sea at Tsushima, the first modern defeat of a European power by an Asian one; the Treaty of Portsmouth ended it.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Russo-Japanese_War' },
    { t: ymd(1905, 1, 22), title: 'Bloody Sunday sparks the 1905 Russian Revolution',
      detail: 'Troops fired on workers marching to the Winter Palace with a petition for Tsar Nicholas II, setting off a year of strikes, mutinies and peasant risings that forced the October Manifesto and Russia\'s first elected Duma.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Bloody_Sunday_(1905)' },
    // 18 Mar 1905 (photoelectric paper received) – 27 Sep 1905 (mass–energy paper received)
    { t: ymd(1905, 3, 18), end: ymd(1905, 9, 27), title: 'Einstein\'s miracle year: special relativity and E = mc²',
      detail: 'In four papers written while working as a Swiss patent clerk, Albert Einstein explained the photoelectric effect, proved atoms exist via Brownian motion, and introduced special relativity and mass–energy equivalence.',
      tier: 3, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Annus_mirabilis_papers' },
    { t: ymd(1908, 10, 1), title: 'Ford introduces the Model T',
      detail: 'Henry Ford\'s cheap, rugged car, built from 1913 on the first moving assembly line, put America on wheels: 15 million were sold and the price fell from $850 to under $300.',
      tier: 5, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Ford_Model_T' },
    { t: ymd(1909, 4, 6), title: 'Peary claims to have reached the North Pole',
      detail: 'Robert Peary, Matthew Henson and four Inuit companions, Ootah, Egingwah, Seegloo and Ooqueah, reported reaching the pole by sledge; the claim was long accepted but is now widely doubted.',
      tier: 6, category: 'exploration',
      link: 'https://en.wikipedia.org/wiki/Robert_Peary' },
    { t: ymd(1909, 7, 2), title: 'Haber demonstrates ammonia synthesis from nitrogen and hydrogen',
      detail: 'Fritz Haber\'s high-pressure apparatus in Karlsruhe produced liquid ammonia from the air\'s nitrogen; scaled up by Carl Bosch at BASF in 1913, the process now makes the fertilizer that feeds about half of humanity.',
      tier: 4, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Haber_process' },
    { t: ymd(1910, 11, 20), end: ymd(1920, 12, 1), title: 'Mexican Revolution',
      detail: 'Francisco Madero\'s call to arms against the dictator Porfirio Díaz unleashed a decade of civil war involving Villa, Zapata, Carranza and Obregón that killed perhaps a million people and produced the 1917 Constitution with its land reform and labour rights.',
      tier: 4, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Mexican_Revolution' },
    { t: ymd(1911, 3, 25), title: 'Triangle Shirtwaist Factory fire kills 146 garment workers in New York',
      detail: 'Locked exit doors trapped the workers, mostly young immigrant women, on the upper floors of a Manhattan factory; the deaths spurred factory-safety laws and the growth of the garment workers\' unions.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Triangle_Shirtwaist_Factory_fire' },
    { t: ymd(1911, 10, 10), end: ymd(1912, 2, 12), title: 'Xinhai Revolution ends two millennia of imperial rule in China',
      detail: 'The Wuchang Uprising spread across the provinces until the six-year-old Puyi abdicated; Sun Yat-sen\'s republic replaced the Qing dynasty, though warlordism and civil war soon followed.',
      tier: 4, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/1911_Revolution' },
    { t: ymd(1911, 12, 14), title: 'Amundsen reaches the South Pole',
      detail: 'Roald Amundsen\'s five-man Norwegian party reached the pole by dog sled five weeks ahead of Robert Falcon Scott, whose British team died on the return march; the last great geographical prize on Earth had been claimed.',
      tier: 6, category: 'exploration',
      link: 'https://en.wikipedia.org/wiki/Amundsen%27s_South_Pole_expedition' },
    { t: ymd(1912, 4, 15), title: 'RMS Titanic sinks on her maiden voyage',
      detail: 'The largest ship afloat struck an iceberg in the North Atlantic and went down with about 1,500 of the 2,200 people aboard; lifeboat rules were overhauled and an international ice patrol created as a result.',
      tier: 6, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Sinking_of_the_Titanic' },
    { t: ymd(1913, 5, 29), title: 'Stravinsky\'s The Rite of Spring provokes a riot at its Paris premiere',
      detail: 'The pounding rhythms and dissonance of Igor Stravinsky\'s ballet for Diaghilev\'s Ballets Russes, with Nijinsky\'s stamping choreography, set off catcalls and fistfights at the Théâtre des Champs-Élysées; it became a cornerstone of modern music.',
      tier: 6, category: 'art',
      link: 'https://en.wikipedia.org/wiki/The_Rite_of_Spring' },
    { t: ymd(1913, 7), title: 'Bohr publishes his quantum model of the atom',
      detail: 'Niels Bohr proposed that electrons occupy fixed orbits and emit light only when jumping between them, explaining the spectrum of hydrogen and bringing Planck\'s quantum into the structure of matter.',
      tier: 5, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Bohr_model' },
    { t: ymd(1914, 6, 28), title: 'Archduke Franz Ferdinand assassinated in Sarajevo',
      detail: 'Gavrilo Princip, a Bosnian Serb nationalist, shot the heir to the Austro-Hungarian throne and his wife; the July Crisis that followed drew the great powers into the First World War within five weeks.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Assassination_of_Archduke_Franz_Ferdinand' },
    { t: ymd(1914, 7, 28), end: ymd(1918, 11, 11), title: 'First World War',
      detail: 'Industrialized total war between the Allies and the Central Powers killed some 20 million people, toppled the Russian, German, Austro-Hungarian and Ottoman empires, and redrew the map of Europe and the Middle East.',
      tier: 0, category: 'war',
      link: 'https://en.wikipedia.org/wiki/World_War_I' },
    { t: ymd(1914, 8, 15), title: 'Panama Canal opens',
      detail: 'The SS Ancon made the first official transit of the 82-km waterway, cutting the voyage from New York to San Francisco by 13,000 km; built by the United States after a French failure, it cost some 5,600 lives, mostly Caribbean workers.',
      tier: 4, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Panama_Canal' },
    { t: ymd(1915, 4, 24), end: ymd(1917), title: 'Armenian genocide in the Ottoman Empire',
      detail: 'Ottoman authorities arrested Armenian leaders in Constantinople and then deported the empire\'s Armenians on death marches into the Syrian desert; an estimated 600,000 to 1.5 million died, one of the crimes Raphael Lemkin had in mind when he coined the word genocide.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Armenian_genocide' },
    { t: ymd(1915, 11, 25), title: 'Einstein presents the general theory of relativity',
      detail: 'Einstein gave the Prussian Academy of Sciences his final field equations, describing gravity as the curvature of spacetime; Eddington\'s 1919 eclipse expedition confirmed the predicted bending of starlight and made Einstein world-famous.',
      tier: 4, category: 'science',
      link: 'https://en.wikipedia.org/wiki/General_relativity' },
    { t: ymd(1917, 11, 7), title: 'Bolsheviks seize power in the October Revolution',
      detail: 'Lenin\'s Bolsheviks stormed the Winter Palace in Petrograd and overthrew the Provisional Government, creating the world\'s first communist state and shaping global politics for the rest of the century.',
      tier: 1, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/October_Revolution' },
    { t: ymd(1918, 3, 4), end: ymd(1920, 4), title: '1918 influenza pandemic',
      detail: 'An H1N1 strain spread worldwide in three waves, infecting about a third of humanity and killing an estimated 50 million people, more than the war it accompanied.',
      tier: 3, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/Spanish_flu' },
    { t: ymd(1919, 4, 13), title: 'Jallianwala Bagh massacre in Amritsar',
      detail: 'Brigadier Reginald Dyer ordered his troops to fire without warning on thousands of unarmed Indians gathered in a walled garden, killing at least 379; the massacre turned Gandhi and millions of Indians decisively against British rule.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Jallianwala_Bagh_massacre' },
    { t: ymd(1919, 6, 28), title: 'Treaty of Versailles signed',
      detail: 'Five years to the day after Sarajevo, the Allies imposed territorial losses, disarmament and reparations on Germany and created the League of Nations; resentment of the treaty fuelled the rise of the Nazis.',
      tier: 4, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Treaty_of_Versailles' },

    // ---- 1920s -----------------------------------------------------------------------
    { t: ymd(1920, 8, 18), title: '19th Amendment gives American women the vote',
      detail: 'Tennessee\'s ratification, carried by a single vote, made women\'s suffrage part of the US Constitution after a 72-year campaign that began at Seneca Falls.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Nineteenth_Amendment_to_the_United_States_Constitution' },
    { t: ymd(1921, 7, 23), title: 'Chinese Communist Party holds its founding congress in Shanghai',
      detail: 'Thirteen delegates, among them Mao Zedong, met in secret in the French Concession with two Comintern advisers to found a party of some 50 members; it would win control of China in 1949 and rule it ever since.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Chinese_Communist_Party' },
    { t: ymd(1922, 1, 11), title: 'Insulin first used to treat a diabetic patient',
      detail: 'Fourteen-year-old Leonard Thompson received the first injection of insulin at Toronto General Hospital; a purified dose on 23 January restored him, and Banting, Best, Collip and Macleod\'s extract turned type 1 diabetes from a death sentence into a manageable condition.',
      tier: 5, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/Frederick_Banting' },
    { t: ymd(1922, 10, 28), title: "Mussolini's March on Rome brings the Fascists to power",
      detail: 'Blackshirt columns converged on Rome; King Victor Emmanuel III refused to declare martial law and instead asked Mussolini to form a government, installing the first fascist regime in Europe.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/March_on_Rome' },
    { t: ymd(1922, 11, 4), title: 'Howard Carter finds the tomb of Tutankhamun',
      detail: 'Carter\'s team uncovered the steps to the most intact royal tomb ever found in the Valley of the Kings; its golden treasures set off a worldwide craze for ancient Egypt.',
      tier: 7, category: 'exploration',
      link: 'https://en.wikipedia.org/wiki/Tomb_of_Tutankhamun' },
    { t: ymd(1922, 12, 30), title: 'Union of Soviet Socialist Republics founded',
      detail: 'Delegates of the Russian, Ukrainian, Byelorussian and Transcaucasian Soviet republics signed the treaty creating the USSR in Moscow, the one-party federal state that would last until December 1991.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Treaty_on_the_Creation_of_the_USSR' },
    { t: ymd(1923, 10, 29), title: 'Republic of Turkey proclaimed with Atatürk as its first president',
      detail: 'The Grand National Assembly in Ankara proclaimed a republic under Mustafa Kemal, completing the replacement of the Ottoman Empire, whose sultanate had been abolished in 1922; the caliphate followed in March 1924.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Mustafa_Kemal_Atat%C3%BCrk' },
    { t: ymd(1926, 1, 26), title: 'Baird gives the first public demonstration of television',
      detail: 'In his Soho attic laboratory, John Logie Baird showed members of the Royal Institution live moving images of a ventriloquist\'s dummy and his business partner, transmitted by a mechanical scanning disc.',
      tier: 5, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/John_Logie_Baird' },
    { t: ymd(1926, 3, 16), title: 'Goddard launches the first liquid-fuelled rocket',
      detail: 'Robert Goddard\'s gasoline-and-liquid-oxygen rocket flew for about two and a half seconds from a farm in Auburn, Massachusetts, the technical ancestor of every launch vehicle since.',
      tier: 6, category: 'space',
      link: 'https://en.wikipedia.org/wiki/Robert_H._Goddard' },
    { t: ymd(1927, 5, 20), end: ymd(1927, 5, 21), title: 'Lindbergh flies solo across the Atlantic',
      detail: 'Charles Lindbergh flew the Spirit of St Louis nonstop from New York to Paris in 33 and a half hours, the first solo transatlantic flight, and became the most famous man in the world overnight.',
      tier: 7, category: 'exploration',
      link: 'https://en.wikipedia.org/wiki/Spirit_of_St._Louis' },
    { t: ymd(1928, 9, 3), title: 'Fleming discovers penicillin',
      detail: 'Returning from holiday to his St Mary\'s Hospital lab, Alexander Fleming noticed a mould killing bacteria on a discarded culture plate, the first antibiotic; Florey and Chain turned it into a mass-produced drug by 1943.',
      tier: 2, category: 'medicine',
      link: 'https://en.wikipedia.org/wiki/Alexander_Fleming' },
    { t: ymd(1929, 3, 15), title: 'Hubble shows the universe is expanding',
      detail: 'Edwin Hubble\'s paper showed that galaxies recede at speeds proportional to their distance, the observational foundation of the Big Bang model.',
      tier: 5, category: 'space',
      link: 'https://en.wikipedia.org/wiki/Hubble%27s_law' },
    { t: ymd(1929, 10, 29), title: 'Black Tuesday: Wall Street crash sets off the Great Depression',
      detail: 'Panic selling on the New York Stock Exchange wiped out billions in days and helped tip the world into a decade-long depression that put a quarter of American workers out of a job and fed political extremism.',
      tier: 3, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Wall_Street_crash_of_1929' },

    // ---- 1930s -----------------------------------------------------------------------
    { t: ymd(1930, 3, 12), end: ymd(1930, 4, 6), title: 'Gandhi leads the Salt March',
      detail: 'Mohandas Gandhi walked 385 km from Sabarmati to Dandi to make salt in defiance of the British monopoly, sparking mass civil disobedience across India and drawing world attention to its independence movement.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Salt_March' },
    { t: ymd(1931, 9, 18), title: 'Japan invades Manchuria after the Mukden Incident',
      detail: 'Officers of Japan\'s Kwantung Army blew up a stretch of the South Manchuria Railway near Mukden as a pretext to seize all of Manchuria, set up the puppet state of Manchukuo in 1932 and lead Japan out of the League of Nations.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Mukden_Incident' },
    { t: ymd(1932), end: ymd(1933, 12, 31), title: 'Holodomor: famine kills millions in Soviet Ukraine',
      detail: 'Stalin\'s forced collectivization and ruthless grain requisitions, enforced by sealing Ukraine\'s borders, starved an estimated 3.5 to 5 million people to death; Ukraine and many other countries recognize it as a genocide.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Holodomor' },
    { t: ymd(1932, 2, 27), title: 'Chadwick discovers the neutron',
      detail: 'James Chadwick\'s letter to Nature, dated 17 February and published on 27 February, identified the uncharged particle in the atomic nucleus, completing the picture of the atom and opening the way to nuclear fission.',
      tier: 6, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Discovery_of_the_neutron' },
    { t: ymd(1932, 9, 23), title: 'Kingdom of Saudi Arabia proclaimed by Ibn Saud',
      detail: 'Abdulaziz ibn Saud, who had retaken Riyadh in 1902 and conquered the Hejaz with its holy cities in 1925, merged his domains into a single kingdom; the discovery of oil at Dammam in 1938 would make it one of the world\'s richest states.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Unification_of_Saudi_Arabia' },
    { t: ymd(1933, 1, 30), title: 'Hitler appointed Chancellor of Germany',
      detail: 'President Hindenburg named Adolf Hitler head of a coalition government; within months the Nazis had used the Reichstag fire and the Enabling Act to turn the Weimar Republic into a one-party dictatorship.',
      tier: 3, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Adolf_Hitler%27s_rise_to_power' },
    { t: ymd(1934, 10, 16), end: ymd(1935, 10, 22), title: 'Long March of the Chinese Communists',
      detail: 'Breaking out of a Nationalist encirclement in Jiangxi, some 86,000 Red Army soldiers marched about 9,000 km over mountains and rivers to Shaanxi; fewer than 10,000 arrived, but Mao Zedong emerged as the party\'s leader.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Long_March' },
    { t: ymd(1936, 5, 28), title: 'Turing submits "On Computable Numbers"',
      detail: 'Alan Turing\'s paper defined a universal machine that could compute anything computable and proved some problems undecidable, laying the theoretical foundation of computer science.',
      tier: 5, category: 'computing',
      link: 'https://en.wikipedia.org/wiki/Turing%27s_proof' },
    { t: ymd(1936, 7, 17), end: ymd(1939, 4, 1), title: 'Spanish Civil War',
      detail: 'A military rising led by Franco against the Republic drew in Germany and Italy on one side and the Soviet Union and international volunteers on the other; some 500,000 died before Madrid fell and Franco ruled until 1975.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Spanish_Civil_War' },
    { t: ymd(1937, 5, 6), title: 'Hindenburg airship bursts into flames at Lakehurst',
      detail: 'The hydrogen-filled German zeppelin caught fire while mooring in New Jersey, killing 36; captured on newsreel and radio, the disaster ended the era of passenger airships.',
      tier: 7, category: 'technology',
      link: 'https://en.wikipedia.org/wiki/Hindenburg_disaster' },
    { t: ymd(1937, 7, 7), title: 'Marco Polo Bridge Incident starts the Second Sino-Japanese War',
      detail: 'A clash between Japanese and Chinese troops at the Marco Polo Bridge outside Beijing escalated into full-scale war, the Asian beginning of the Second World War, which would kill some 15 to 20 million Chinese.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Marco_Polo_Bridge_Incident' },
    { t: ymd(1937, 12, 13), title: 'Nanjing Massacre begins as Japanese troops take the Chinese capital',
      detail: 'Over roughly six weeks after the city fell, the Imperial Japanese Army killed tens of thousands of prisoners and civilians, with estimates reaching 300,000, and raped tens of thousands of women.',
      tier: 6, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Nanjing_Massacre' },
    { t: ymd(1938, 11, 9), title: 'Kristallnacht pogrom across Germany and Austria',
      detail: 'Nazi paramilitaries burned hundreds of synagogues, smashed Jewish shops and sent 30,000 Jewish men to concentration camps in a night of state-organized violence that foreshadowed the Holocaust.',
      tier: 6, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Kristallnacht' },
    { t: ymd(1938, 12, 17), title: 'Hahn and Strassmann discover nuclear fission',
      detail: 'In Berlin, Otto Hahn and Fritz Strassmann found barium among the products of neutron-bombarded uranium; Lise Meitner and Otto Frisch explained that the nucleus had split, releasing enormous energy.',
      tier: 4, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Discovery_of_nuclear_fission' },
    { t: ymd(1939, 9, 1), end: ymd(1945, 9, 2), title: 'Second World War',
      detail: 'Germany\'s invasion of Poland began the deadliest conflict in history, which killed 70–85 million people, ended with atomic bombs and left the United States and Soviet Union as rival superpowers.',
      tier: 0, category: 'war',
      link: 'https://en.wikipedia.org/wiki/World_War_II' },

    // ---- 1940s -----------------------------------------------------------------------
    // Year precision is deliberate: there is no canonical start date for the Holocaust.
    { t: ymd(1941), end: ymd(1945, 5, 8), title: 'The Holocaust',
      detail: 'Nazi Germany and its collaborators systematically murdered six million Jews, along with Roma, disabled people, Poles, Soviet prisoners and others, in mass shootings and purpose-built death camps such as Auschwitz.',
      tier: 2, category: 'war',
      link: 'https://en.wikipedia.org/wiki/The_Holocaust' },
    { t: ymd(1941, 5, 12), title: 'Zuse demonstrates the Z3, the first programmable digital computer',
      detail: 'Konrad Zuse presented his relay-based machine to aeronautical researchers in Berlin; program-controlled, fully automatic and working in binary floating point, it was the first computer of its kind to run, though it was destroyed in an air raid in 1943.',
      tier: 5, category: 'computing',
      link: 'https://en.wikipedia.org/wiki/Z3_(computer)' },
    { t: ymd(1941, 6, 22), title: 'Operation Barbarossa: Germany invades the Soviet Union',
      detail: 'Some three million Axis troops attacked along a 2,900-km front in the largest invasion in history, opening the Eastern Front, where most of the war\'s fighting and dying took place and where Nazi Germany would ultimately be broken.',
      tier: 4, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Operation_Barbarossa' },
    { t: ymd(1941, 12, 7), title: 'Japan attacks Pearl Harbor',
      detail: 'Carrier aircraft struck the US Pacific Fleet in Hawaii, sinking four battleships and killing 2,400 Americans; the United States declared war the next day, and Germany followed, making the war truly global.',
      tier: 4, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Attack_on_Pearl_Harbor' },
    { t: ymd(1942, 8, 23), end: ymd(1943, 2, 2), title: 'Battle of Stalingrad',
      detail: 'The Red Army encircled and destroyed the German Sixth Army in the ruins of Stalingrad, at a cost of nearly two million casualties on both sides; it marked the turning point of the war in Europe.',
      tier: 5, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Battle_of_Stalingrad' },
    { t: ymd(1943), end: ymd(1944), title: 'Bengal famine kills some three million people',
      detail: 'Wartime disruption, the loss of Burmese rice, hoarding, inflation and the British government\'s refusal to divert shipping to relief left Bengal to starve; an estimated two to three million died, one of the deadliest famines of the century.',
      tier: 5, category: 'agriculture',
      link: 'https://en.wikipedia.org/wiki/Bengal_famine_of_1943' },
    { t: ymd(1944, 6, 6), title: 'D-Day: Allied forces land in Normandy',
      detail: 'Some 156,000 American, British and Canadian troops landed on five beaches in the largest seaborne invasion in history, opening the Western Front that would liberate France and drive into Germany.',
      tier: 4, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Normandy_landings' },
    { t: ymd(1944, 7, 1), end: ymd(1944, 7, 22), title: 'Bretton Woods conference designs the postwar economic order',
      detail: 'Delegates from 44 Allied nations meeting in New Hampshire created the International Monetary Fund and the World Bank and pegged currencies to a gold-backed US dollar, a system that governed world finance until 1971.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Bretton_Woods_Conference' },
    { t: ymd(1945), end: ymd(1975), title: 'Decolonization of Asia and Africa',
      detail: 'In three decades after the Second World War the European empires dissolved: India and Pakistan in 1947, Indonesia in 1949, most of Africa around 1960 and Portugal\'s colonies in 1975, creating dozens of new states and reshaping the United Nations.',
      tier: 2, category: 'empire',
      link: 'https://en.wikipedia.org/wiki/Decolonization' },
    { t: ymd(1945, 5, 8), title: 'VE Day: Germany surrenders unconditionally',
      detail: 'A week after Hitler\'s suicide in Berlin, the Wehrmacht\'s surrender took effect and crowds celebrated across Europe and America; the war continued against Japan.',
      tier: 6, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Victory_in_Europe_Day' },
    { t: ymd(1945, 6, 26), title: 'United Nations Charter signed in San Francisco',
      detail: 'Delegates from 50 nations signed the founding treaty of the United Nations, creating the Security Council and General Assembly to prevent another world war; it took effect on 24 October 1945.',
      tier: 4, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Charter_of_the_United_Nations' },
    { t: ymd(1945, 7, 16), title: 'Trinity: the first atomic bomb is tested in New Mexico',
      detail: 'At 5:29 a.m. the Manhattan Project\'s plutonium implosion device exploded in the Jornada del Muerto desert with the force of about 21,000 tons of TNT, lighting the sky brighter than day and proving the weapon that would be used on Japan three weeks later.',
      tier: 4, category: 'science',
      link: 'https://en.wikipedia.org/wiki/Trinity_(nuclear_test)' },
    { t: ymd(1945, 8, 6), title: 'Atomic bomb destroys Hiroshima',
      detail: 'The US B-29 Enola Gay dropped the uranium bomb Little Boy on Hiroshima, killing around 80,000 people instantly; a second bomb hit Nagasaki three days later, opening the nuclear age.',
      tier: 1, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Atomic_bombings_of_Hiroshima_and_Nagasaki' },
    { t: ymd(1945, 8, 17), title: 'Sukarno proclaims the independence of Indonesia',
      detail: 'Two days after Japan\'s surrender, Sukarno and Mohammad Hatta read a brief proclamation in Jakarta declaring the Dutch East Indies independent; four years of war and diplomacy followed before the Netherlands recognized the republic in 1949.',
      tier: 5, category: 'politics',
      link: 'https://en.wikipedia.org/wiki/Proclamation_of_Indonesian_Independence' },
    { t: ymd(1945, 9, 2), title: 'Japan signs the surrender aboard USS Missouri in Tokyo Bay',
      detail: 'Foreign Minister Shigemitsu signed the instrument of surrender before General MacArthur, formally ending the Second World War; the day is marked as VJ Day in the United States.',
      tier: 7, category: 'war',
      link: 'https://en.wikipedia.org/wiki/Japanese_Instrument_of_Surrender' }
  );
})(typeof window !== 'undefined' ? window : globalThis);
